  Lemma model0_lazy : m_vm_lazy model0 = [].
Proof.
ltac2:(KReplay.run1 (kr_t_Eu0Usage ()) ["FPX_1"; "Usage"] "p;1p;2g0000j10Tg000Uj16Tg0013j12Tg003Yj21Tg0049j15Tg004Yj14Tg002Zj23Tg0034#0#0#0#0#0#0#6#2R0/10R0#5%40'3o"). Qed.
  Lemma model0_fd2 : fd_lookup (m_fds model0) (Z_to_bv 64 2) = Some (FdChannel (Z_to_bv 64 2)).
Proof.
ltac2:(KReplay.run1 (kr_t_Eu0Usage ()) ["FPX_1"; "Usage"] "p;1p;2p10059p4p70p1005gp4p710p8g001Vj17Tg0000j10Tg000Uj12Tg006Cj11Tg006aj26Tg007Gj15Tg008?j23Tg002Zj24Tg008aR0#7g0034#0R1#0#0#0#0#0#2%11'6#5,30'4o"). Qed.
  Lemma model0_fs : m_fs model0 = fs0.
Proof.
ltac2:(KReplay.run1 (kr_t_Eu0Usage ()) ["FPX_1"; "Usage"] "p;2g002Zj20Tg0059p,3fs0'0o"). Qed.

